          { en: "I've been working on the report all day.", de: 'Ich arbeite den ganzen Tag am Bericht. (Dauer zählt)' },
          { en: "She's read three books this month.", de: 'Sie hat diesen Monat drei Bücher gelesen. (Anzahl/Ergebnis)' }
