          { type: 'choice', topic: 'that-for-things', prompt: 'Which is correct?', options: ['The performance review that I had yesterday went well.', 'The performance review who I had yesterday went well.'], answerIndex: 0, explanation: '"Performance review" ist eine Sache → "that", nicht "who".' },
          { type: 'gap', topic: 'line-manager-defining', prompt: 'Speak to the line manager ___ is responsible for your department.', answer: ['who', 'that'], explanation: 'Definierender Relativsatz zu einer Person → "who"/"that".', hintSentence: 'Sprich mit dem Vorgesetzten, der für deine Abteilung zuständig ist.' },
          { type: 'choice', topic: 'omission-object-relative', prompt: 'In casual speech, which relative pronoun can usually be dropped?', options: ['The subject of the clause (e.g. "who" before a verb)', 'The object of the clause (e.g. "that/which/who" before a subject+verb)'], answerIndex: 1, explanation: 'Nur das Objekt-Relativpronomen kann in informeller Sprache wegfallen, das Subjekt-Pronomen nie.' }
